"""Field definitions remain available without interrupting the article."""
from .tool_help_catalog import GUIDES

SYSTEM_FIELDS=[
('Cargar sistema','El mismo menú permite abrir un JSON exportado por SignalLab o usar un resultado anterior. Se conservan dominio, secciones SOS y avances temporales. Cargar prepara los datos: calculá en esta herramienta para obtener su análisis. No se convierte automáticamente entre continuo y discreto.'),
('Dominio y definición','H(s) corresponde a un sistema continuo y H(z) a uno discreto. Podés ingresar una fórmula racional o los coeficientes de su numerador y denominador.'),
('Orden de los coeficientes','En continuo, 1,2,3 representa s²+2s+3. En discreto, representa 1+2z⁻¹+3z⁻². Conservá los ceros intermedios; cada posición corresponde a una potencia.'),
('Frecuencias y puntos','Desde y Hasta delimitan el intervalo evaluado e incluyen sus extremos. Usá rad/s para H(s) o rad/muestra para H(z). Puntos controla cuántas evaluaciones se hacen, sin cambiar los coeficientes.'),
('Eje lineal o logarítmico','El eje lineal permite cero y frecuencias negativas. El logarítmico exige un inicio positivo y distribuye las evaluaciones por décadas, por ejemplo entre 1,10 y 100; no cambia sólo las marcas del gráfico.'),
('Módulo lineal o dB','La barra de la figura permite cambiar la presentación del mismo resultado mediante 20·log10|H|. Un cero exacto tiene −∞ dB y no se dibuja como un valor finito. Cambiar esta vista no recalcula H.'),
('Polos y ceros','La pestaña consulta las raíces del resultado calculado en coordenadas binómicas o polares. Los ceros son círculos y los polos cruces. Si coinciden en el origen se muestran ambas marcas y su cantidad; el ángulo de una raíz nula no está definido.'),
('Cruces y márgenes','Al activar esta opción, H se interpreta como el lazo abierto L de una realimentación negativa unitaria. Se admiten los casos indicados de coeficientes reales, sin avance temporal. El cruce |L|=1 permite calcular margen de fase; en un cruce con el eje real negativo, el margen de ganancia es 1/|L|.'),
('Cómo leer los márgenes','Los márgenes de fase se expresan en radianes con signo en [−π,π). Se buscan cruces aislados dentro del intervalo y pueden quedar cruces sin detectar entre evaluaciones. En discreto se usa 0<ω≤π. La ausencia de cruces no significa margen infinito y un margen positivo no prueba por sí solo estabilidad del lazo cerrado.'),
('Realización','La pestaña muestra sumadores, ganancias y retardos o integradores del sistema analizado. Los bloques verdes generan los estados q; los ámbar multiplican por −a[k] y los azules por b[k]. Sus ecuaciones y coeficientes se explican en el informe del diagrama.'),
('Matrices y período T','Desde Realización se puede enviar el modelo a Espacio de estados. En discreto, T se expresa en segundos y establece su reloj físico; no cambia H(z). Una H(s) impropia requiere derivadores y un avance digital no se representa como una cadena causal de retardos.'),
('Sistemas con avance','Un factor z^m con m positivo representa avance, no retardo. El análisis conserva ese factor en la fórmula, fase, retardo y plano. Se guarda en el sistema exportado y al enviarlo a diseño o Z inversa. Las operaciones que necesitan una recurrencia causal no lo sustituyen por otro filtro.'),
('Exportar y reutilizar','Las acciones toman el último sistema calculado. Si editás el formulario, el aviso Datos modificados indica que todavía debés recalcular para actualizarlo. Una fórmula con parámetros libres requiere valores antes de reutilizar un sistema numérico.'),
('Exportar respuesta','CSV conserva el eje, H compleja, módulo, dB, fase y retardo; JSON agrega los cruces y sus condiciones. Los valores no definidos se guardan vacíos en CSV y como null en JSON. Una frecuencia logarítmica no tiene paso constante y se conserva como tabla de análisis.')]

def _field_rows(route):
    from .visual_help import PARAMETERS
    key=tuple(route[1:3])
    if key==('course_tools','phase'):
        return [('Estudio','Fase mínima y paso todo conserva la factorización existente. Compensar módulo y fase diseña un FIR causal C para la cascada H·C; no cambia H.'),
        ('Banda de ajuste','Desde y Hasta cumplen 0 ≤ Desde < Hasta ≤ π y usan rad/muestra. El ajuste se hace sobre la respuesta compleja en esa banda, con puntos de comprobación adicionales.'),
        ('Coeficientes y retardo','La cantidad de coeficientes es un entero positivo. D es un retardo entero no negativo del objetivo H·C. Una longitud o retardo insuficientes pueden dar un error alto; la herramienta muestra el resultado obtenido, sin declararlo exacto.'),
        ('Ganancia objetivo','Es una amplitud positiva para la cascada, no para C aislado. El objetivo complejo es ganancia·exp(−iωD).'),
        ('Regularización λ','Es un número no negativo. Se suma λ·Σ|c[k]|² al promedio del error complejo relativo cuadrático. Cero elimina esa penalización. Un valor mayor suele reducir coeficientes grandes, pero puede empeorar el ajuste.'),
        ('Qué se exporta','El selector distingue C del sistema compensado H·C. Las acciones de sistemas usan el elegido; Exportar comparación CSV guarda H, C, H·C y el objetivo dentro de la banda. La gráfica de comparación evalúa el producto sin expandirlo.'),
        ('Transferencia conjunta','Cuando puede representarse con precisión, H·C se ofrece como otro sistema reutilizable. Si la forma polinómica pierde precisión respecto del producto, se informa y se conservan C y la comparación, sin publicar esa transferencia conjunta.'),
        ('Error y estabilidad','El RMS y el máximo se evalúan en una rejilla más densa que la del ajuste; no prueban una cota continua. C es FIR estable. El diseño no estabiliza H ni cancela modos internos; se rechazan sus polos causales no estables.'),
        ('Lectura de fase y retardo','La comparación muestra el error angular principal respecto del objetivo, en radianes. Se omite donde la respuesta es cero. El retardo de H·C se obtiene sumando los de H y C, con ejes de frecuencia comunes.')]+GUIDES[key]['parameters']
    if key==('transform_lab','z'):
        return GUIDES[key]['parameters']+[
            ('Analizar X(z) como H(z)','En Directa y Muestras finitas se usa la transformada del último resultado calculado. En Inversa se usa la X(z) ingresada en ese momento, sin exigir calcular primero la inversa. Se copia al análisis de sistemas para consultar frecuencia, retardo y polos/ceros. Debe ser una expresión racional con valores numéricos; los avances se conservan. Allí se calcula el análisis con sus propios datos.'),
            ('Valores dentro de la fórmula','Si los radicales exactos harían ilegible el resultado, se muestran números evaluados dentro de la propia expresión. Los coeficientes, módulos y ángulos se presentan con al menos 17 cifras significativas. No necesitás sustituir letras de una tabla. Las raíces exactas se conservan para el cálculo y los parámetros sin asignar siguen siendo simbólicos.'),
            ('Fórmula y muestras','Las fracciones parciales se calculan mediante operaciones polinómicas. En tramos causales iniciales se puede usar una recurrencia exacta; para otros índices se evalúan los términos con precisión ampliada antes de convertir las muestras a doble precisión. El intervalo no recorta la fórmula ni cambia la ROC.')]
    if key==('course_tools','phase'):
        return [('Estudio','Factorizar y compensar trabajan con H(z). Reconstruir usa datos independientes: módulo lineal, dB o fase desenrollada.'),('Período completo','Las fórmulas y listas cubren −π a π con el extremo final repetido. La cantidad incluye ambos extremos: paso=2π/(cantidad−1). Un archivo puede incluir un período completo uniforme o 0…π con Completar por simetría real. Esta última opción presupone un sistema real y no sirve para un módulo asimétrico de un sistema complejo. Otra banda parcial requiere hipótesis adicionales.'),('Desplazamiento d','Positivo retrasa y negativo adelanta. Desde módulo es una elección adicional; desde fase debe ser un dato conocido para quitar esa pendiente antes de reconstruir. La herramienta no inventa el retardo perdido.'),('Fase constante','Desde módulo, se elige un giro constante adicional en radianes. El módulo no permite saber ese giro.'),('Módulo en frecuencia cero','Desde fase se necesita una referencia positiva de ganancia. Cambiarla escala todo el módulo y no cambia la fase.'),('Piso del módulo','Cero conserva los datos y rechaza módulos nulos. Un valor positivo sustituye los valores menores antes del logaritmo: cambia el modelo y se informa cuántos puntos toca. Se expresa siempre en amplitud lineal, incluso si la entrada está en dB.'),('Resolución','Se compara con una rejilla de la mitad de puntos cuando es posible. No es una cota de error del sistema real. La convención para el armónico Nyquist de una rejilla par puede impedir una ida y vuelta exacta entre módulo y fase.'),('Resultados','H es una respuesta compleja exportable y reutilizable en filtros definidos en frecuencia. h[n] es un registro aproximado de la inversa, no los coeficientes de un FIR exacto. El CSV conserva módulo, dB, fase y retardo; el JSON de H guarda el modelo cepstral.') ]
    if key==('sampling',5):
        return [('Estudio','Representar un número muestra la palabra y el error de conversión. Coeficientes de un filtro compara H(z) con su almacenamiento. Filtrar con precisión finita añade entrada propia y redondeos de ejecución.'),
        ('Formato','Q es punto fijo con signo en complemento a dos. binary16, binary32 y binary64 son formatos IEEE 754 con 5/8/11 bits de exponente y 10/23/52 bits de fracción, además del signo.'),
        ('Bits de punto fijo','Los bits enteros I incluyen el signo; F indica bits fraccionarios. El paso es 2^(−F) y el rango va de −2^(I−1) a 2^(I−1)−2^(−F).'),
        ('Redondeo','En Q, redondear desempata alejándose de cero y truncar se acerca a cero. Fuera del rango se satura. IEEE 754 usa el más cercano con empates al par y conserva subnormales y cero con signo.'),
        ('Valor','Se admite una constante como 0.7, 1/3 o pi. Los racionales se interpretan exactamente. Las constantes irracionales se aproximan a 100 cifras y el informe lo indica; no se atribuye al error más exactitud que a esa referencia.'),
        ('Realización de H(z)','Conservar secciones mantiene las SOS recibidas y cuantiza cada una. Polinomios directos expande los coeficientes de la definición. Los formatos pueden afectar de manera distinta a ambas representaciones.'),
        ('Denominador normalizado','a[0]=1 no se almacena como un coeficiente de la recurrencia y queda fijo. No se redondea ni se renormaliza el filtro después de cuantizar los demás coeficientes.'),
        ('Comparación y alcance','En Coeficientes, las figuras comparten frecuencias en rad/muestra y se comparan radios de polos; Hq se evalúa después en doble precisión. En Filtrar, se comparan secuencias sobre los mismos índices, con redondeos internos según el modo elegido. Las referencias usan doble precisión.'),
        ('Entrada y memorias','La entrada puede ser fórmula, muestras, archivo o resultado. Un valor inicial se aplica a todas las memorias; una lista sigue el orden d[0], d[1], … y, en SOS, dos por sección. No son salidas anteriores y[n−1].'),
        ('Redondeos de ejecución','Productos, sumas, salida y memorias redondea cada operación real. Sólo salida y memorias conserva precisión entre conversiones. Los complejos se calculan por componentes con cuatro productos y dos sumas, sin multiplicación/suma fusionada.'),
        ('Rango y desbordes','Los bits extra amplían sólo la parte entera del acumulador Q. Saturar limita el valor; el complemento a dos cíclico lo devuelve al rango por módulo 2 elevado al número de bits. La tabla de coeficientes usa siempre saturación Q. Los contadores distinguen cada etapa.'),
        ('Ceros y ciclos','Los ceros agregados permiten ver la cola. Un ciclo se confirma con igualdad exacta del estado interno durante entrada nula. El informe distingue un estado periódico no nulo del reposo; la observación tiene la duración del registro.'),
        ('Exportación','Para números, JSON guarda la palabra completa y los valores de referencia. Para filtros, CSV guarda cada coeficiente y sus bits, y las acciones de filtro exportan o reutilizan Hq. En ejecución, Comparación exporta un CSV con ambas referencias; Salida y exporta o reutiliza la secuencia y su JSON conserva parámetros, contadores y estados. Los cambios pendientes no alteran el último resultado.')]
    if key==('system_analysis',0):return SYSTEM_FIELDS
    if key==('transform_lab','laplace'):return GUIDES[key]['parameters']+[
        ('Analizar X(s) como H(s)','En Directa se usa la transformada del último resultado calculado. En Inversa se usa la X(s) ingresada en ese momento, sin exigir calcular primero la inversa. La acción copia la expresión racional numérica al análisis de sistemas para consultar frecuencia, retardo y polos/ceros. Los parámetros libres requieren valores. La transformación y sus resultados se conservan.'),
    ]
    if key==('interconnection',0):return [
        ('Definición de H₁ y H₂','Cada pestaña permite usar fórmula racional, coeficientes o Cargar sistema. Esa acción abre un JSON o copia un resultado anterior sólo al bloque seleccionado. Ambos bloques deben tener el mismo dominio.'),
        ('Retardos y avances','Las conexiones conservan las potencias positivas y negativas de z. El sistema equivalente puede ser no causal: podés analizar su frecuencia y su inversa Z, pero una simulación causal requiere una realización sin avances.'),
        ('Entrada y resultado','Editar un bloque no modifica el último sistema calculado. El aviso Datos modificados indica que debés calcular otra vez. Analizar, Usar sistema en y Exportar sistema trabajan con ese último resultado.'),
    ]+GUIDES[key]['parameters']
    if key==('course_tools','fir'):
        return PARAMETERS[key]+[(name,text) for name,text in GUIDES[key]['parameters'] if name=='Estimación Kaiser']
    if key==('course_tools','iir'):return PARAMETERS[key]
    return GUIDES[key]['parameters']


def field_rows(route):
    rows=_field_rows(route);key=tuple(route[1:3])
    systems=key in {('system_analysis',0),('systems',9),('systems',6),('interconnection',0),('course_tools','gain'),('course_tools','phase'),('sampling',5)} or key[0]=='state_space'
    if systems:
        text='El mismo menú abre un JSON de sistema o reutiliza un resultado anterior. El selector incluye sistemas y expresiones guardadas en s o z, filtrados por el dominio permitido. Las expresiones deben ser racionales y tener coeficientes numéricos; al cargar se interpretan como H(s) o H(z). Se conservan los coeficientes, las secciones y el reloj físico disponible. Una operación causal rechaza avances. Cargar prepara los datos: después calculá el estudio en esta herramienta.'
        rows=[('Cargar sistema',text)]+[(name,body) for name,body in rows if name!='Cargar sistema']
    if key[0] in ('expression_measures','fourier_symbolic','dtft_symbolic'):
        rows=rows+[('Reutilizar una expresión','El selector muestra definiciones compatibles con la variable y, si está declarada, la unidad de esta herramienta. Copiar una fórmula conserva sus condiciones y la relación con el resultado original. Editarla prepara una definición independiente. En Energía/potencia también podés copiar la señal de entrada de una medición anterior; no se usa su valor de energía como señal.')]
    if key[0] in ('fourier_symbolic','dtft_symbolic','inverse_dtft') or key in (('fourier',0),('fourier',1),('fourier',3),('basic','dft'),('course_tools','fft')):
        rows=rows+[('Cambiar entre numérico y algebraico','Al abrir por primera vez una variante compatible, se copia la definición. Si ya tiene datos propios, se conservan y aparece un enlace para copiar voluntariamente. En DTFT se mantienen los índices del soporte. En Fourier continua, pasar de numérico a algebraico limita la fórmula al intervalo observado; pasar al numérico requiere revisar inicio, cantidad y paso.'),('Fórmula y registro','La fórmula algebraica se integra dentro del soporte indicado. El método numérico aproxima a partir de muestras: no se afirma que ambos resultados sean idénticos con una rejilla finita. Una tabla o un archivo de muestras no determina una fórmula analítica única y no se convierte en una fórmula inventada.'),('Directa e inversa','La directa recibe x(t) o x[n]. La inversa recibe X(ω). Sus entradas no se copian una sobre otra al cambiar de operación. Para trabajar con una salida calculada, elegila desde Resultados o usá su acción de reutilización.')]
    if key==('course_tools','convert'):
        rows=rows+[('Cortes de referencia Ωc','Campo opcional en rad/s. Admite uno o varios valores separados por coma, como pi o expresiones constantes. Sólo se usan para mostrar dónde quedan los cortes; no rediseñan la transferencia. Vacío usa los cruces analógicos a −3.0103 dB respecto del máximo evaluado.'),('Corte mapeado y corte medido','Bilineal usa ωc=2·atan(ΩcT/2). Invarianza usa ΩcT módulo 2π, pero el aliasing puede alterar el corte real. El informe muestra por separado los cruces del filtro resultante a su máximo/√2, el máximo de referencia y el intervalo evaluado. Ese criterio no equivale a cualquier borde de tolerancia de un diseño.'),('Relación s/z y transferencia','El informe presenta H de entrada, las ecuaciones del mapeo y la transferencia resultante. En invarianza, z=exp(sT) mapea polos: no es una sustitución general de toda H. Los coeficientes de cada resultado se conservan al exportar o reutilizar.'),('Módulo lineal o dB','El selector del resultado y el de la barra de la figura cambian la presentación entre |H| y 20·log10|H| sin rediseñar el filtro. Módulo, fase y retardo pueden mostrarse juntos; el cambio de escala conserva el intervalo ampliado del gráfico.')]
    if key[0]=='transform_lab':
        rows=rows+[('Resultado y CAS','Enviar a CAS agrega la última expresión calculada a la hoja, con sus condiciones y ROC. No envía una entrada modificada que todavía no calculaste. Allí podés operar con la referencia rN y conservar el trabajo anterior.'),('Z inversa por propiedades','Cuando se reconocen pares geométricos, se aplican linealidad y desplazamiento antes de la descomposición general. Por ejemplo, 2/(1-exp(-0.2)*z^(-1))-1/(1-exp(-0.4)*z^(-1)) con ROC exterior produce (2*exp(-n/5)-exp(-2*n/5))*u[n]. La ROC determina si cada término es derecho o izquierdo; otra ROC puede dar una secuencia diferente. Las expresiones que no forman estos pares siguen el método racional general.')]
    if key[0] in ('basic','time_transform','correlation','signal_product','fourier','systems'):
        rows=rows+[('Impulso discreto o continuo','En discreto, impulse(n-a) es la muestra unitaria en n=a. En una entrada temporal continua, DiracDelta(t-a), dirac(t-a) e impulse(t-a) guardan posición y peso, separados de la parte ordinaria; no se fija una altura de muestra. Las operaciones que no admiten distribuciones explican el límite. La página DiracDelta de Funciones de las fórmulas muestra la diferencia con un dibujo de colores.')]
    if key in {('fourier',0),('fourier',1),('fourier',3),('fourier_symbolic',0),('fourier_symbolic',1),('dtft_symbolic',0),('dtft_symbolic',1),('inverse_dtft',0),('basic','dft'),('basic','idft'),('course_tools','fft')}:
        rows=rows+[('Qué transformada elegir','DFT / FFT trabaja con N coeficientes de un registro finito; FFT es el algoritmo que calcula la DFT. DTFT conserva una curva continua en ω para una secuencia, periódica cada 2π rad/muestra. Fourier continua usa x(t) y Ω en rad/s. El dibujo compara sus entradas y salidas.'),('Dirección y estudio','Directa transforma una señal; Inversa recibe su espectro o sus coeficientes. Cambiar de transformada conserva la dirección si está disponible. Cada vista mantiene sus datos. Dentro de DFT directa, Estudio elige Transformada o Ventanas y resolución, sin crear otra herramienta.')]
    if key in {('course_tools','fir'),('course_tools','iir'),('course_tools','analog'),('systems',0),('fir_window',0),('systems',6),('systems',1),('systems',8),('systems',2)}:
        rows=rows+[('Elegir la definición del filtro','Diseñar por reúne bandas y tolerancias, respuesta FIR, polos y ceros, segundo orden y circuito RC. Sólo aparecen Dominio o Estructura si hay varias opciones para ese caso. Las h[n] por ventana son digitales; RC es analógico. En el editor de raíces se elige allí s o z.'),('Cambiar de definición','Cada formulario conserva sus parámetros. Las especificaciones digitales FIR e IIR pueden copiar bandas y tolerancias compatibles; rad/s y rad/muestra no se intercambian sin conversión. Para analizar o reutilizar un filtro ya calculado, usá Usar filtro en… o Resultados.')]
    if key==('course_tools','fir'):
        rows=rows+[('Dos transiciones en un pasabanda','Izquierda: ωp1−ωs1. Derecha: ωs2−ωp2. Con rechazo 0.25*pi y 0.65*pi, y paso 0.35*pi y 0.60*pi, los anchos son 0.10*pi y 0.05*pi. Son distintos aunque la banda de paso sea una sola. Para dos anchos de 0.10*pi en ese ejemplo, el rechazo superior empezaría en 0.70*pi.'),('Especificación y respuesta enventanada','Las franjas coloreadas muestran dónde se permite la transición; no miden la anchura que ocupa la curva. Kaiser estima la longitud con la menor transición y la menor tolerancia. Cada corte del ideal se coloca a mitad de sus bordes; una ventana común puede completar antes una transición que tenga más margen. El informe conserva los anchos y el criterio usado.')]
    return rows
